using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAtUtc)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        // Server-side prerender: returns empty; real data comes via API after auth hydration
        return await Task.FromResult(new List<ShipmentDto>());
    }

    public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<ShipmentDto?> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = request.Origin,
            Destination = request.Destination,
            RecipientName = request.RecipientName,
            CustomerEmail = request.CustomerEmail,
            Status = (int)ShipmentStatus.Pending,
            CreatedAtUtc = DateTime.UtcNow,
            EstimatedDeliveryUtc = request.EstimatedDeliveryUtc,
            Notes = request.Notes
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task<bool> UpdateStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return false;

        shipment.Status = (int)request.Status;
        if (request.Notes is not null)
            shipment.Notes = request.Notes;
        if (request.Status == ShipmentStatus.Delivered)
            shipment.DeliveredAtUtc = DateTime.UtcNow;

        await db.SaveChangesAsync();
        return true;
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        CreatedAtUtc = s.CreatedAtUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        DeliveredAtUtc = s.DeliveredAtUtc,
        RecipientName = s.RecipientName,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAtUtc)
                .ToListAsync();

            return Results.Ok(shipments.Select(ToDto));
        });

        group.MapGet("/mine", async (ClaimsPrincipal user, ApplicationDbContext db) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
            if (email is null) return Results.Unauthorized();

            var shipments = await db.Shipments
                .Where(s => s.CustomerEmail == email)
                .OrderByDescending(s => s.CreatedAtUtc)
                .ToListAsync();

            return Results.Ok(shipments.Select(ToDto));
        });

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            return shipment is null ? Results.NotFound() : Results.Ok(ToDto(shipment));
        }).AllowAnonymous();

        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (CreateShipmentRequest request, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}",
                Origin = request.Origin,
                Destination = request.Destination,
                RecipientName = request.RecipientName,
                CustomerEmail = request.CustomerEmail,
                Status = (int)ShipmentStatus.Pending,
                CreatedAtUtc = DateTime.UtcNow,
                EstimatedDeliveryUtc = request.EstimatedDeliveryUtc,
                Notes = request.Notes
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            return Results.Created($"api/shipments/track/{shipment.TrackingNumber}", ToDto(shipment));
        });

        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (int)request.Status;
            if (request.Notes is not null)
                shipment.Notes = request.Notes;
            if (request.Status == ShipmentStatus.Delivered)
                shipment.DeliveredAtUtc = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(ToDto(shipment));
        });
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        CreatedAtUtc = s.CreatedAtUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        DeliveredAtUtc = s.DeliveredAtUtc,
        RecipientName = s.RecipientName,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    };
}

