@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>📦 Dispatcher Dashboard</h2>

<div class="d-flex justify-content-between align-items-center mb-3">
    <div>
        <input class="form-control" placeholder="Filter by destination…" @bind="filterText" @bind:event="oninput" style="width: 300px;" />
    </div>
    <button class="btn btn-primary" @onclick="() => showCreateForm = !showCreateForm">
        @(showCreateForm ? "Cancel" : "+ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Recipient Name</label>
                    <input class="form-control" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Customer Email</label>
                    <input class="form-control" type="email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Estimated Delivery (UTC)</label>
                    <input class="form-control" type="datetime-local" @bind="newShipment.EstimatedDeliveryUtc" />
                </div>
                <div class="col-12">
                    <label class="form-label">Notes</label>
                    <input class="form-control" @bind="newShipment.Notes" />
                </div>
                <div class="col-12">
                    <button class="btn btn-success" @onclick="CreateShipment" disabled="@isCreating">
                        @(isCreating ? "Creating…" : "Create Shipment")
                    </button>
                </div>
            </div>
            @if (createError is not null)
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments…</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDeliveryUtc?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                        @onchange="e => UpdateStatus(s, e)">
                                    <option value="">Change…</option>
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        if (status != s.Status)
                                        {
                                            <option value="@((int)status)">@status</option>
                                        }
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="text-muted">—</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private bool showCreateForm;
    private bool isCreating;
    private string? createError;
    private CreateShipmentRequest newShipment = new();

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrWhiteSpace(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.RecipientName.Contains(filterText, StringComparison.OrdinalIgnoreCase)
        ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        createError = null;
        try
        {
            var result = await ShipmentService.CreateShipmentAsync(newShipment);
            if (result is not null)
            {
                shipments?.Insert(0, result);
                newShipment = new();
                showCreateForm = false;
            }
            else
            {
                createError = "Failed to create shipment. Please check your input.";
            }
        }
        catch (Exception ex)
        {
            createError = $"Error: {ex.Message}";
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (e.Value is string val && int.TryParse(val, out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            var success = await ShipmentService.UpdateStatusAsync(shipment.Id, new UpdateShipmentStatusRequest { Status = newStatus });
            if (success)
            {
                shipment.Status = newStatus;
                if (newStatus == ShipmentStatus.Delivered)
                    shipment.DeliveredAtUtc = DateTime.UtcNow;
            }
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>My Shipments</PageTitle>

<h2>📋 My Shipments</h2>

@if (shipments is null)
{
    <p><em>Loading your shipments…</em></p>
}
else if (!shipments.Any())
{
    <p>You have no shipments. Use the tracking page to look up a shipment by tracking number.</p>
}
else
{
    <div class="row">
        @foreach (var s in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@s.TrackingNumber</code>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Recipient:</strong> @s.RecipientName</p>
                        @if (s.EstimatedDeliveryUtc.HasValue)
                        {
                            <p class="mb-1">
                                <strong>Est. Delivery:</strong>
                                @s.EstimatedDeliveryUtc.Value.ToString("MMM dd, yyyy")
                                @if (s.Status != ShipmentStatus.Delivered && s.EstimatedDeliveryUtc.Value > DateTime.UtcNow)
                                {
                                    <span class="text-muted">
                                        (@((int)(s.EstimatedDeliveryUtc.Value - DateTime.UtcNow).TotalDays) days remaining)
                                    </span>
                                }
                            </p>
                        }
                        @if (s.DeliveredAtUtc.HasValue)
                        {
                            <p class="mb-1 text-success">
                                <strong>Delivered:</strong> @s.DeliveredAtUtc.Value.ToString("MMM dd, yyyy HH:mm") UTC
                            </p>
                        }
                        @if (!string.IsNullOrEmpty(s.Notes))
                        {
                            <p class="mb-0 text-muted"><small>@s.Notes</small></p>
                        }
                    </div>
                    <div class="card-footer">
                        <ShipmentProgressBar Status="s.Status" />
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? shipments;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetMyShipmentsAsync();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track a Shipment</PageTitle>

<h2>🔍 Track a Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g. SHP-20260620-100001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isSearching">
