@using ShipmentTracker.Client.Models

<div class="d-flex justify-content-between align-items-center mt-2">
    @foreach (var step in steps)
    {
        var reached = (int)Status >= step.Order;
        var isCancelled = Status == ShipmentStatus.Cancelled;
        <div class="text-center flex-fill">
            <div class="@(isCancelled ? "text-danger" : reached ? "text-success" : "text-muted")">
                <span style="font-size: 1.2rem;">@(reached ? "●" : "○")</span>
            </div>
            <small class="@(isCancelled && step.Order == 0 ? "text-danger" : reached ? "text-success" : "text-muted")">
                @step.Label
            </small>
        </div>
    }
</div>

@code {
    [Parameter] public ShipmentStatus Status { get; set; }

    private static readonly (int Order, string Label)[] steps =
    [
        (0, "Pending"),
        (1, "Picked Up"),
        (2, "In Transit"),
        (3, "Out for Delivery"),
        (4, "Delivered")
    ];
}

